import * as THREE from 'three';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

// Textura del torpedo embebida en base64
const TEXTURA = 'data:image/png;base64,';

// ---------------------------------------------------------------------------
// Ajustes
// ---------------------------------------------------------------------------
const CONFIG = {
  image: TEXTURA, // PNG embebido: sin esto, abrir con file:// ensucia el canvas
                  // y getImageData falla al trazar la silueta
  height: 3.6, // alto del torpedo en unidades de escena
  thickness: 0.32, // grosor, como fracción del ancho

  removeBackground: true,
  keyColor: '#ffffff',
  keyThreshold: 0.04,
  keySoftness: 0.05,

  traceWidth: 220, // resolución a la que se rastrea la silueta
  traceThreshold: 140, // alfa mínimo para considerar "material"
  smoothPasses: 3, // suavizado del contorno

  bodyTint: '#e08a5c', // se multiplica sobre la foto: más oscuro = naranja más profundo
  edgeDarken: 0.42, // qué tan oscuro es el naranja del canto (1 = igual a la cara)
  envIntensity: 0.4, // fuerza de los reflejos del entorno

  ropeColor: '#f7f6f2',
  ropeAccent: '#15161a',
  ropeRadius: 0.055,
  ropeInsert: 0.45, // cuánto se mete la punta de la cuerda dentro del cuerpo

  anchorMargin: 1.6, // distancia desde el borde izquierdo del lienzo, en unidades
  segments: 6,
  segmentLength: 1.3,
  anchorY: 7.2,
  gravity: -48,
  damping: 0.985,
  iterations: 14
};

// ---------------------------------------------------------------------------
// Texturas generadas por código
// ---------------------------------------------------------------------------
function seededRandom(seed) {
  return function () {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Cuerda de nylon. El canvas es cuadrado para que las motas no se deformen
 *  al envolver el tubo; el sombreado cilíndrico lo dan las luces, no la textura. */
function makeRopeTexture(base, accent) {
  const S = 256;
  const canvas = document.createElement('canvas');
  canvas.width = canvas.height = S;
  const ctx = canvas.getContext('2d');

  ctx.fillStyle = base;
  ctx.fillRect(0, 0, S, S);

  // hebras del trenzado, apenas insinuadas
  ctx.strokeStyle = 'rgba(0,0,0,0.06)';
  ctx.lineWidth = 9;
  for (let x = -S; x < S * 2; x += 26) {
    ctx.beginPath();
    ctx.moveTo(x, -10);
    ctx.lineTo(x + S * 0.5, S + 10);
    ctx.stroke();
  }

  // motas, repetidas a los costados para que la textura calce al repetirse
  const rnd = seededRandom(11);
  ctx.fillStyle = accent;
  for (let i = 0; i < 7; i++) {
    const x = rnd() * S;
    const y = rnd() * S;
    const rx = 11 + rnd() * 8;
    const ry = 5 + rnd() * 3.5;
    const rot = 1.0 + rnd() * 0.5;
    for (const ox of [-S, 0, S]) {
      for (const oy of [-S, 0, S]) {
        ctx.beginPath();
        ctx.ellipse(x + ox, y + oy, rx, ry, rot, 0, Math.PI * 2);
        ctx.fill();
      }
    }
  }

  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.anisotropy = 8;
  return tex;
}

/** Borra del PNG todo lo que se parezca al color de fondo. */
function cutout(img) {
  const canvas = document.createElement('canvas');
  canvas.width = img.width;
  canvas.height = img.height;
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  ctx.drawImage(img, 0, 0);

  if (!CONFIG.removeBackground) return canvas;

  let data;
  try {
    data = ctx.getImageData(0, 0, canvas.width, canvas.height);
  } catch {
    return canvas; // pasa si abrís el HTML sin servidor
  }

  const key = new THREE.Color(CONFIG.keyColor);
  const kr = key.r * 255;
  const kg = key.g * 255;
  const kb = key.b * 255;
  const t0 = CONFIG.keyThreshold * 441.67;
  const t1 = (CONFIG.keyThreshold + CONFIG.keySoftness) * 441.67;
  const px = data.data;

  for (let i = 0; i < px.length; i += 4) {
    const dr = px[i] - kr;
    const dg = px[i + 1] - kg;
    const db = px[i + 2] - kb;
    const dist = Math.sqrt(dr * dr + dg * dg + db * db);

    let a = 1;
    if (dist <= t0) a = 0;
    else if (dist < t1) a = (dist - t0) / (t1 - t0);
    if (a === 1) continue;

    if (a > 0.02) {
      px[i] = Math.max(0, Math.min(255, (px[i] - kr * (1 - a)) / a));
      px[i + 1] = Math.max(0, Math.min(255, (px[i + 1] - kg * (1 - a)) / a));
      px[i + 2] = Math.max(0, Math.min(255, (px[i + 2] - kb * (1 - a)) / a));
    }
    px[i + 3] = Math.round(a * 255);
  }

  ctx.putImageData(data, 0, 0);
  return canvas;
}

// ---------------------------------------------------------------------------
// Silueta -> geometría. Marching squares sobre el canal alfa: devuelve el
// contorno exterior y los de las agarraderas, listos para extruir.
// ---------------------------------------------------------------------------
function traceContours(alpha, w, h, threshold) {
  const solid = (x, y) => x >= 0 && y >= 0 && x < w && y < h && alpha[y * w + x] >= threshold;
  const k = p => `${p[0]}|${p[1]}`;
  const starts = new Map();

  const push = (a, b) => {
    const key = k(a);
    if (!starts.has(key)) starts.set(key, []);
    starts.get(key).push(b);
  };

  for (let y = -1; y < h; y++) {
    for (let x = -1; x < w; x++) {
      const tl = solid(x, y);
      const tr = solid(x + 1, y);
      const br = solid(x + 1, y + 1);
      const bl = solid(x, y + 1);
      const code = (tl ? 8 : 0) | (tr ? 4 : 0) | (br ? 2 : 0) | (bl ? 1 : 0);
      if (code === 0 || code === 15) continue;

      const T = [x + 0.5, y];
      const R = [x + 1, y + 0.5];
      const B = [x + 0.5, y + 1];
      const L = [x, y + 0.5];

      switch (code) {
        case 1: push(L, B); break;
        case 2: push(B, R); break;
        case 3: push(L, R); break;
        case 4: push(R, T); break;
        case 5: push(L, T); push(R, B); break;
        case 6: push(B, T); break;
        case 7: push(L, T); break;
        case 8: push(T, L); break;
        case 9: push(T, B); break;
        case 10: push(T, R); push(B, L); break;
        case 11: push(T, R); break;
        case 12: push(R, L); break;
        case 13: push(R, B); break;
        case 14: push(B, L); break;
      }
    }
  }

  // Encadena los segmentos sueltos en bucles cerrados
  const loops = [];
  for (const [startKey, ends] of starts) {
    while (ends.length) {
      const loop = [];
      let cur = startKey.split('|').map(Number);
      let next = ends.pop();
      loop.push(cur);

      while (next) {
        loop.push(next);
        const list = starts.get(k(next));
        if (!list || !list.length) break;
        next = list.pop();
        if (k(next) === startKey) break;
      }
      if (loop.length > 8) loops.push(loop);
    }
  }
  return loops;
}

/** Área con signo: sirve para saber cuál bucle es el contorno exterior. */
function loopArea(loop) {
  let a = 0;
  for (let i = 0; i < loop.length; i++) {
    const p = loop[i];
    const q = loop[(i + 1) % loop.length];
    a += p[0] * q[1] - q[0] * p[1];
  }
  return a / 2;
}

/** Menos puntos y esquinas redondeadas: el trazado sale escalonado por píxel. */
function simplify(loop, keep, passes) {
  const step = Math.max(1, Math.floor(loop.length / keep));
  let pts = loop.filter((_, i) => i % step === 0);
  for (let p = 0; p < passes; p++) {
    pts = pts.map((pt, i) => {
      const a = pts[(i - 1 + pts.length) % pts.length];
      const b = pts[(i + 1) % pts.length];
      return [(a[0] + pt[0] * 2 + b[0]) / 4, (a[1] + pt[1] * 2 + b[1]) / 4];
    });
  }
  return pts;
}

function buildGeometry(canvas, planeW, planeH) {
  // Se rastrea a baja resolución: más rápido y el contorno sale más limpio
  const tw = CONFIG.traceWidth;
  const th = Math.round((tw * canvas.height) / canvas.width);
  const small = document.createElement('canvas');
  small.width = tw;
  small.height = th;
  const sctx = small.getContext('2d', { willReadFrequently: true });
  sctx.drawImage(canvas, 0, 0, tw, th);

  const data = sctx.getImageData(0, 0, tw, th).data;
  const alpha = new Uint8Array(tw * th);
  for (let i = 0; i < alpha.length; i++) alpha[i] = data[i * 4 + 3];

  const loops = traceContours(alpha, tw, th, CONFIG.traceThreshold);
  if (!loops.length) return null;

  const minArea = tw * th * 0.002; // descarta ruido suelto
  const valid = loops.filter(l => Math.abs(loopArea(l)) > minArea);
  if (!valid.length) return null;

  valid.sort((a, b) => Math.abs(loopArea(b)) - Math.abs(loopArea(a)));

  // De píxeles a unidades de escena, centrado en el origen
  const toWorld = pt => new THREE.Vector2(
    ((pt[0] + 0.5) / tw - 0.5) * planeW,
    (0.5 - (pt[1] + 0.5) / th) * planeH
  );

  const outer = simplify(valid[0], 140, CONFIG.smoothPasses).map(toWorld);
  const shape = new THREE.Shape(outer);

  for (let i = 1; i < valid.length; i++) {
    const hole = simplify(valid[i], 70, CONFIG.smoothPasses).map(toWorld);
    shape.holes.push(new THREE.Path(hole));
  }

  const thickness = planeW * CONFIG.thickness;
  const geo = new THREE.ExtrudeGeometry(shape, {
    depth: thickness * 0.55,
    bevelEnabled: true,
    bevelThickness: thickness * 0.22,
    bevelSize: planeW * 0.022, // chico: si crece, se come las paredes de las ranuras
    bevelOffset: 0,
    bevelSegments: 6
  });

  // UV plana referida a la imagen completa, así la foto calza exactamente
  const pos = geo.attributes.position;
  const uv = geo.attributes.uv;
  for (let i = 0; i < pos.count; i++) {
    uv.setXY(i, pos.getX(i) / planeW + 0.5, pos.getY(i) / planeH + 0.5);
  }

  uv.needsUpdate = true;

  geo.computeBoundingBox();
  const bb = geo.boundingBox;
  geo.translate(0, 0, -(bb.min.z + bb.max.z) / 2);
  geo.computeVertexNormals();
  return geo;
}

/** Color representativo del objeto. El promedio simple sale lavado porque
 *  mezcla los brillos blancos; acá se descartan los píxeles poco saturados y
 *  se toma un percentil bajo de luminancia, que es el naranja "real". */
function dominantColor(canvas) {
  const ctx = canvas.getContext('2d', { willReadFrequently: true });
  const px = ctx.getImageData(0, 0, canvas.width, canvas.height).data;
  const samples = [];

  for (let i = 0; i < px.length; i += 4) {
    if (px[i + 3] < 200) continue;
    const r = px[i];
    const g = px[i + 1];
    const b = px[i + 2];
    const max = Math.max(r, g, b);
    const min = Math.min(r, g, b);
    if (max === 0 || (max - min) / max < 0.2) continue; // brillos y grises
    samples.push([r, g, b, 0.299 * r + 0.587 * g + 0.114 * b]);
  }

  if (!samples.length) return new THREE.Color(0xdd4400);
  samples.sort((a, b) => a[3] - b[3]);
  const pick = samples[Math.floor(samples.length * 0.45)];
  return new THREE.Color(pick[0] / 255, pick[1] / 255, pick[2] / 255);
}

/** Tapa lo transparente con un color sólido. Como la geometría ya recorta la
 *  silueta, el relleno solo asoma en el borde y evita que se vea calado. */
function fillTransparent(canvas, color) {
  const out = document.createElement('canvas');
  out.width = canvas.width;
  out.height = canvas.height;
  const ctx = out.getContext('2d');
  ctx.fillStyle = `#${color.getHexString()}`;
  ctx.fillRect(0, 0, out.width, out.height);
  ctx.drawImage(canvas, 0, 0);
  return out;
}

// ---------------------------------------------------------------------------
// Escena
// ---------------------------------------------------------------------------
const container = document.getElementById('lanyard');

// En pantallas chicas el canvas se come el ancho útil, y con movimiento
// reducido el balanceo molesta más de lo que aporta.
const corresponde =
  container &&
  window.innerWidth > 1100 &&
  !window.matchMedia('(prefers-reduced-motion: reduce)').matches;

if (!corresponde) {
  if (container) container.hidden = true;
} else {

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(20, container.clientWidth / container.clientHeight, 0.1, 100);
  camera.position.set(0, 0, 32);

  const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
  renderer.setSize(container.clientWidth, container.clientHeight);
  renderer.setClearColor(0x000000, 0);
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  container.appendChild(renderer.domElement);

  // Entorno de estudio generado al vuelo: da reflejos suaves y hace que el
  // plástico se lea como plástico. Sin esto el color queda chato.
  const pmrem = new THREE.PMREMGenerator(renderer);
  scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;

  // Luz suave: la foto ya trae su propio sombreado, así que las luces solo
  // tienen que revelar el volumen y darle brillo a la cuerda.
  scene.add(new THREE.AmbientLight(0xffffff, 0.85));

  const keyLight = new THREE.DirectionalLight(0xffffff, 1.35);
  keyLight.position.set(3.5, 6, 7);
  keyLight.castShadow = true;
  keyLight.shadow.mapSize.set(1024, 1024);
  keyLight.shadow.camera.left = -5;
  keyLight.shadow.camera.right = 5;
  keyLight.shadow.camera.top = 7;
  keyLight.shadow.camera.bottom = -7;
  keyLight.shadow.camera.near = 0.5;
  keyLight.shadow.camera.far = 30;
  keyLight.shadow.bias = -0.0009;
  keyLight.shadow.normalBias = 0.03;
  scene.add(keyLight);

  const fillLight = new THREE.DirectionalLight(0xffffff, 0.35);
  fillLight.position.set(-6, -2, 4);
  scene.add(fillLight);

  // ---------------------------------------------------------------------------
  // Física: Verlet con restricciones de distancia
  // ---------------------------------------------------------------------------
  class Particle {
    constructor(x, y) {
      this.pos = new THREE.Vector3(x, y, 0);
      this.prev = this.pos.clone();
      this.pinned = false;
    }
    step(dt) {
      if (this.pinned) return;
      const px = this.pos.x;
      const py = this.pos.y;
      this.pos.x += (this.pos.x - this.prev.x) * CONFIG.damping;
      this.pos.y += (this.pos.y - this.prev.y) * CONFIG.damping + CONFIG.gravity * dt * dt;
      this.prev.set(px, py, 0);
    }
  }

  function constrain(a, b, len) {
    const dx = b.pos.x - a.pos.x;
    const dy = b.pos.y - a.pos.y;
    const d = Math.hypot(dx, dy) || 0.0001;
    const diff = (d - len) / d / 2;
    const ox = dx * diff;
    const oy = dy * diff;
    if (!a.pinned) {
      a.pos.x += ox;
      a.pos.y += oy;
    }
    if (!b.pinned) {
      b.pos.x -= ox;
      b.pos.y -= oy;
    }
  }

  // El lienzo ocupa todo el hero, así que el torpedo no se recorta nunca.
  // El anclaje se calcula desde el borde izquierdo de la escena, no del div.
  const alturaVisible = 2 * Math.tan((camera.fov * Math.PI) / 360) * camera.position.z;
  const anclaX = () => -(alturaVisible * camera.aspect) / 2 + CONFIG.anchorMargin;

  const particles = [];
  for (let i = 0; i <= CONFIG.segments; i++) {
    particles.push(new Particle(anclaX(), CONFIG.anchorY - i * CONFIG.segmentLength));
  }
  particles[0].pinned = true;

  const nose = particles[particles.length - 1];
  const tail = new Particle(anclaX(), nose.pos.y - CONFIG.height);
  particles.push(tail);

  // ---------------------------------------------------------------------------
  // Objetos visibles
  // ---------------------------------------------------------------------------
  const ropeTexture = makeRopeTexture(CONFIG.ropeColor, CONFIG.ropeAccent);
  const ropeMaterial = new THREE.MeshStandardMaterial({
    map: ropeTexture,
    roughness: 0.75,
    metalness: 0,
    envMapIntensity: CONFIG.envIntensity
  });
  let ropeMesh = null;

  const buoyPivot = new THREE.Group(); // gira con el balanceo
  const buoyMesh = new THREE.Group(); // gira sobre su eje al arrastrar
  buoyPivot.add(buoyMesh);
  let buoyReady = false;

  new THREE.TextureLoader().load(CONFIG.image, texture => {
    const img = texture.image;
    const canvas = cutout(img);

    const planeH = CONFIG.height;
    const planeW = planeH * (img.width / img.height);

    const base = dominantColor(canvas);

    // Naranja oscuro para el interior: el mismo tono de la foto, bajado de brillo
    // y un toque más rojo. La luz y el entorno le dan el degradado.
    const edgeColor = base.clone().multiply(new THREE.Color(CONFIG.bodyTint)).multiplyScalar(CONFIG.edgeDarken);
    edgeColor.g *= 0.93;

    const geo = buildGeometry(canvas, planeW, planeH);

    // Con geometría propia el recorte lo hace la malla, así que la textura va
    // rellena y opaca: sin alphaTest no quedan fisuras entre la cara y el canto.
    const map = new THREE.CanvasTexture(geo ? fillTransparent(canvas, edgeColor) : canvas);
    map.colorSpace = THREE.SRGBColorSpace;
    map.anisotropy = 16;

    const faceMaterial = new THREE.MeshStandardMaterial({
      map,
      color: new THREE.Color(CONFIG.bodyTint), // multiplica sobre la textura
      side: THREE.DoubleSide,
      roughness: 0.5,
      metalness: 0,
      envMapIntensity: CONFIG.envIntensity,
      transparent: !geo,
      alphaTest: geo ? 0 : 0.35
    });

    // ExtrudeGeometry separa en dos grupos: 0 = caras, 1 = paredes y bisel.
    const edgeMaterial = new THREE.MeshStandardMaterial({
      color: edgeColor,
      side: THREE.DoubleSide,
      roughness: 0.45,
      metalness: 0,
      envMapIntensity: CONFIG.envIntensity * 1.6
    });

    const mesh = geo
      ? new THREE.Mesh(geo, [faceMaterial, edgeMaterial])
      : new THREE.Mesh(new THREE.PlaneGeometry(planeW, planeH), faceMaterial);

    mesh.castShadow = true;
    mesh.receiveShadow = true;
    buoyMesh.add(mesh);

    // Casquillo en la nariz: remata la unión y esconde el punto donde la cuerda
    // entra al cuerpo, igual que el herraje del torpedo real.
    if (geo) {
      geo.computeBoundingBox();
      const grommet = new THREE.Mesh(
        new THREE.CylinderGeometry(CONFIG.ropeRadius * 2.1, CONFIG.ropeRadius * 2.6, 0.17, 20),
        new THREE.MeshStandardMaterial({
          color: 0x9aa0a8,
          roughness: 0.35,
          metalness: 0.9,
          envMapIntensity: CONFIG.envIntensity * 2
        })
      );
      grommet.position.y = geo.boundingBox.max.y - 0.04;
      grommet.castShadow = true;
      buoyMesh.add(grommet);
    }
    scene.add(buoyPivot);
    buoyReady = true;
  });

  function updateRope() {
    const points = particles.slice(0, CONFIG.segments + 1).map(p => p.pos.clone());

    // Punto extra siguiendo el eje nariz->cola: la cuerda entra alineada con el
    // cuerpo y queda tapada por él. Prolongarla en la dirección del último tramo
    // la hacía asomar de costado cada vez que el torpedo se balanceaba.
    const axis = tail.pos.clone().sub(nose.pos).normalize();
    points.push(nose.pos.clone().addScaledVector(axis, CONFIG.ropeInsert));

    const curve = new THREE.CatmullRomCurve3(points, false, 'chordal');
    const geo = new THREE.TubeGeometry(curve, 48, CONFIG.ropeRadius, 12, false);

    // Repetición calculada para que las motas salgan redondas y no ovaladas
    const circumference = 2 * Math.PI * CONFIG.ropeRadius;
    ropeTexture.repeat.set(curve.getLength() / circumference, 1);

    if (ropeMesh) {
      ropeMesh.geometry.dispose();
      ropeMesh.geometry = geo;
    } else {
      ropeMesh = new THREE.Mesh(geo, ropeMaterial);
      ropeMesh.castShadow = true;
      ropeMesh.receiveShadow = true;
      scene.add(ropeMesh);
    }
  }

  // ---------------------------------------------------------------------------
  // Arrastre
  // ---------------------------------------------------------------------------
  const pointer = new THREE.Vector2();
  const raycaster = new THREE.Raycaster();
  const dragPlane = new THREE.Plane(new THREE.Vector3(0, 0, 1), 0);
  const hit = new THREE.Vector3();
  let dragTarget = null;
  const dragOffset = new THREE.Vector3();

  function pointerToWorld(event) {
    const rect = renderer.domElement.getBoundingClientRect();
    pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
    pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
    raycaster.setFromCamera(pointer, camera);
    raycaster.ray.intersectPlane(dragPlane, hit);
    return hit;
  }

  window.addEventListener('pointerdown', event => {
    if (!buoyReady) return;
    const rect = renderer.domElement.getBoundingClientRect();
    pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
    pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
    raycaster.setFromCamera(pointer, camera);
    if (raycaster.intersectObject(buoyPivot, true).length === 0) return;

    const world = pointerToWorld(event);
    dragTarget = world.distanceTo(nose.pos) < world.distanceTo(tail.pos) ? nose : tail;
    dragOffset.copy(dragTarget.pos).sub(world);
    document.body.style.cursor = 'grabbing';
  });

  window.addEventListener('pointermove', event => {
    if (!dragTarget) return;
    const world = pointerToWorld(event);
    dragTarget.pos.copy(world).add(dragOffset);
  });

  const endDrag = () => {
    dragTarget = null;
    document.body.style.cursor = 'auto';
  };
  window.addEventListener('pointerup', endDrag);
  window.addEventListener('pointercancel', endDrag);

  // ---------------------------------------------------------------------------
  // Bucle
  // ---------------------------------------------------------------------------
  const dt = 1 / 60;
  let spin = 0;
  let spinVel = 0;
  let lastX = 0;

  function animate() {
    requestAnimationFrame(animate);

    for (const p of particles) {
      if (p !== dragTarget) p.step(dt);
    }

    for (let k = 0; k < CONFIG.iterations; k++) {
      for (let i = 0; i < CONFIG.segments; i++) {
        constrain(particles[i], particles[i + 1], CONFIG.segmentLength);
      }
      constrain(nose, tail, CONFIG.height);
      if (dragTarget) dragTarget.prev.copy(dragTarget.pos);
    }

    if (buoyReady) {
      const cx = (nose.pos.x + tail.pos.x) / 2;
      const cy = (nose.pos.y + tail.pos.y) / 2;
      buoyPivot.position.set(cx, cy, 0);
      buoyPivot.rotation.z = Math.atan2(tail.pos.x - nose.pos.x, -(tail.pos.y - nose.pos.y));

      // Giro sobre el eje vertical: el movimiento lateral lo empuja y un resorte
      // lo devuelve de frente. Es lo que deja ver que tiene volumen.
      spinVel += (cx - lastX) * 0.32;
      spinVel -= spin * 0.03;
      spinVel *= 0.93;
      spin = THREE.MathUtils.clamp(spin + spinVel, -0.5, 0.5);
      buoyMesh.rotation.y = spin;
      lastX = cx;
    }

    updateRope();
    renderer.render(scene, camera);
  }
  animate();

  window.addEventListener('resize', () => {
    const previo = anclaX();
    camera.aspect = container.clientWidth / container.clientHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(container.clientWidth, container.clientHeight);

    // Al cambiar el ancho se mueve el borde izquierdo: arrastramos toda la
    // cuerda con él para que el torpedo no salga disparado.
    const dx = anclaX() - previo;
    for (const p of particles) {
      p.pos.x += dx;
      p.prev.x += dx;
    }
  });
}
